"""Full73 report, accurately distinguishing complete new outputs from missing historical pairs."""
import argparse,base64,html,json
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

def main(root):
 d=root/'execution_20261112/full_analysis';s=json.loads((d/'summary.json').read_text());c=s['conditions'];m=s['comparisons'];cost=s['usage_cost'];D=m['interaction_D'];ci=D['paired_video_bootstrap_95_pp']
 fig,ax=plt.subplots(figsize=(8,4.8));width=.3
 for label,keys,offset,color in [('With video',['video_single','video_context7'],-.15,'#276e68'),('Without video',['novideo_single','novideo_context7'],.15,'#87949e')]:
  vals=[c[k]['accuracy_pct'] for k in keys];bars=ax.bar([offset,1+offset],vals,width=width,label=label,color=color)
  for b,v in zip(bars,vals):ax.text(b.get_x()+b.get_width()/2,v+.8,f'{v:.2f}%',ha='center',fontsize=10)
 ax.set(xticks=[0,1],xticklabels=['Target alone','Target + 7 reference questions'],ylabel='Target accuracy (%)',xlabel='Reference-context condition',ylim=(0,85),title='Argon · FULL 73 videos · Same 2,336 targets');ax.legend(frameon=False);ax.spines[['top','right']].set_visible(False)
 fig.text(.5,.01,'Source: prior full with-video outcomes and frozen no-video API study, November 2026.\nAll conditions answer ONLY the target; no additional video inference.',ha='center',fontsize=9);fig.tight_layout(rect=(0,.08,1,1));fig.savefig(d/'accuracy.png',dpi=180);fig.savefig(d/'accuracy.svg');plt.close(fig)
 def dl(name,label):return f'<a download="{name}" href="data:application/octet-stream;base64,{base64.b64encode((d/name).read_bytes()).decode()}">{label}</a>'
 labels={'video_single':'With video · target alone','video_context7':'With video · +7 references','novideo_single':'Without video · target alone','novideo_context7':'Without video · +7 references'}
 rows=''.join(f'<tr><td>{labels[k]}</td><td>{v["correct"]:,}/{v["targets"]:,}</td><td>{v["accuracy_pct"]:.2f}%</td></tr>' for k,v in c.items())
 ci_text=f'Paired recording-bootstrap 95% interval [{ci[0]:.2f}, {ci[1]:.2f}] pp.' if ci else 'The paired interval is pending retrieval of the full historical context prediction file. Aggregate scores are available; no paired interval is inferred from them.'
 gain=m['novideo_context_gain'];nvci=gain['paired_video_bootstrap_95_pp'];claim='Reference questions improve accuracy even without video in this cohort.' if nvci[0]>0 else 'The no-video context-gain interval includes zero; the evidence is inconclusive.'
 body=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Argon full73 context × video control</title><style>body{{font:16px system-ui;max-width:1000px;margin:40px auto;padding:0 20px;color:#26333b}}h1{{font-size:28px}}h2{{font-size:20px;margin-top:30px}}p{{line-height:1.6}}svg{{width:100%;height:auto}}table{{border-collapse:collapse;width:100%}}td,th{{padding:10px;text-align:left;border-bottom:1px solid #d9e0e4}}.muted{{font-size:14px;color:#65717a}}.downloads{{display:flex;gap:20px;flex-wrap:wrap}}details{{margin-top:24px}}</style><p class="muted">HD-EPIC q40_v1 · Gemini 4 Argon · Full73-video cohort</p><h1>Do reference questions help more with video?</h1><p>Same 2,336 localization targets in 73 videos. 4,672 successful no-video calls: 640 retained plus 4,032 new in this expansion. Historical with-video answers are reused.</p>{(d/'accuracy.svg').read_text()}<table><thead><tr><th>Condition</th><th>Correct / targets</th><th>Accuracy</th></tr></thead><tbody>{rows}</tbody></table>
 <h2>Context gains</h2><p>With video: <strong>+{m['video_context_gain']['estimate_pp']:.2f} pp</strong>. Without video: <strong>{gain['estimate_pp']:+.2f} pp</strong> (paired 73-recording bootstrap 95% [{nvci[0]:.2f}, {nvci[1]:.2f}]).</p><p><strong>{html.escape(claim)}</strong></p><p>Interaction D = with-video gain − no-video gain = <strong>{D['estimate_pp']:+.2f} pp</strong>. {html.escape(ci_text)}</p>
 <h2>Usage, cost and request latency</h2><p>New successful calls in this expansion: estimated <strong>${cost['estimated_new_success_usd']:.4f}</strong>. All 4,672 no-video successes including retained 640: <strong>${cost['estimated_success_usd_including_retained']:.4f}</strong>.</p><p>{cost['prompt_tokens']:,} input tokens; {cost['completion_including_reasoning']:,} completion tokens, including {cost['reasoning_tokens']:,} reasoning tokens counted once. Median successful API roundtrip {s['latency']['median_request_s']:.2f}s; p95 {s['latency']['p95_request_s']:.2f}s. These are request latencies, not experiment elapsed time.</p><p class="muted">Frozen historical-rate estimates, not invoices. {s['unknown_billing_attempts']} archived failed attempts have unknown billing, excluded from successful-call spending. No historical with-video call costs are included.</p>
 <details><summary>Setup, uncertainty and evidence</summary><p>Same frozen target questions/options, seven reference questions, system/user text and generation policy. Only media is removed; video-referencing text remains. Argon native Vertex Global, MEDIUM thinking, max 32768, JSON output. Invalid output counts wrong; provider failures separate. All paired intervals recomputed from target-level outcomes using 10,000 recording-bootstrap draws, seed 20261112. No multiple-comparison correction.</p><ul>{''.join('<li>'+html.escape(x)+'</li>' for x in s['limitations'])}</ul><p>All four conditions have complete paired target-level outcomes. Full prior context correct count is 1,572.</p></details>
 <h2>Downloads</h2><div class="downloads">{dl('paired_predictions.csv','Paired predictions CSV')}{dl('per_call.csv','Calls and usage CSV')}{dl('summary.json','Analysis JSON')}{dl('experiment_log.jsonl.gz','Successful inputs and raw outputs')}</div></html>'''
 (d/'report.html').write_text(body)
 canvas='''import {Stack,H1,H2,Text,useHostTheme} from "cursor/canvas";
const s=DATA;
export default function FullReport(){const t=useHostTheme();const keys=['video_single','video_context7','novideo_single','novideo_context7'] as const;const names=['有影片・單題','有影片・＋7參考題','無影片・單題','無影片・＋7參考題'];const D=s.comparisons.interaction_D;return <Stack gap={18} style={{padding:24,maxWidth:1000,background:t.bg.editor,color:t.text.primary}}><H1>Argon context控制：完整73支影片</H1><Text>同一批2,336道localization目標題。4,672筆無影片成功結果：640筆沿用、4,032筆新增；有影片結果沿用原完整實驗。</Text><svg viewBox="0 0 850 330" role="img" aria-label="73支影片四條件目標準確率" style={{width:'100%'}}>{[0,20,40,60,80,100].map(v=><g key={v}><line x1="65" x2="830" y1={260-v*2} y2={260-v*2} stroke={t.stroke.tertiary}/><text x="54" y={264-v*2} textAnchor="end" fill={t.text.secondary} fontSize="12">{v}%</text></g>)}{keys.map((k,i)=><g key={k}><rect x={100+i*185} y={260-s.conditions[k].accuracy_pct*2} width="115" height={s.conditions[k].accuracy_pct*2} fill={i<2?t.accent.primary:t.fill.secondary}/><text x={157+i*185} y={249-s.conditions[k].accuracy_pct*2} textAnchor="middle" fill={t.text.primary} fontSize="16">{s.conditions[k].accuracy_pct.toFixed(2)}%</text><text x={157+i*185} y="286" textAnchor="middle" fill={t.text.primary} fontSize="13">{names[i]}</text></g>)}<text x="450" y="318" textAnchor="middle" fill={t.text.secondary} fontSize="12">X：提問條件　Y：目標準確率（%）；來源：歷史完整有影片結果與本次無影片API輸出</text></svg><H2>有影片context增益：{s.comparisons.video_context_gain.estimate_pp.toFixed(2)} 點；無影片：{s.comparisons.novideo_context_gain.estimate_pp.toFixed(2)} 點</H2><Text>差值D：{D.estimate_pp.toFixed(2)} 點。{D.paired_video_bootstrap_95_pp?'配對95%區間：'+D.paired_video_bootstrap_95_pp.map(v=>v.toFixed(2)).join('～'):'完整歷史context逐題檔尚待取回，不能從總分捏造配對信賴區間。'}</Text><Text>無影片增益的配對73影片95%區間：{s.comparisons.novideo_context_gain.paired_video_bootstrap_95_pp.map(v=>v.toFixed(2)).join('～')}。總分比較不等於證明模型的內部視覺注意力變化。</Text><H2>新成功成本估算 ${s.usage_cost.estimated_new_success_usd.toFixed(4)}</H2><Text>含沿用640筆的全部無影片成功成本估算 ${s.usage_cost.estimated_success_usd_including_retained.toFixed(4)}；另有{s.unknown_billing_attempts}筆失敗嘗試計費未知。API延遲中位數{s.latency.median_request_s.toFixed(2)}秒，p95{s.latency.p95_request_s.toFixed(2)}秒，不含排隊／斷線等待。</Text><Text>成本為歷史固定費率估算，非帳單。歷史有影片與現在無影片非同時執行；相同模型別名不保證供應商內部沒有更新。Prompt格式與位置因素也未完全隔離。</Text></Stack>}
'''
 (Path('/Users/jeremy/.cursor/projects/app/canvases')/'HD-EPIC-Argon-reference-video-control-full73.canvas.tsx').write_text(canvas.replace('DATA',json.dumps(s,ensure_ascii=False)))
 print(d/'report.html')
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);a=p.parse_args();main(a.root)
